_INJECTION_BLACKLIST = frozenset({";", "|", "&", "$", "`", "\n", "\r"})

@field_validator("name", "command")
@classmethod
def _reject_blacklist_and_empty(cls, value: str) -> str:
    if not value or not value.strip():
        raise ValueError("must not be empty")
    if any(ch in _INJECTION_BLACKLIST for ch in value):
        raise ValueError("contains blacklisted injection character")
    return value

def auth_dep(
    x_api_key: str | None = Header(default=None, alias=_API_KEY_HEADER),
) -> Principal:
    if not x_api_key:
        _reject_unauthorized()
    return rate_dep(_resolve_principal(x_api_key))

def check_scope(principal: Principal, needed: str) -> None:
    if not auth_service.scope_satisfies(needed, principal.scope):
